corrected_code:
import { db } from '../services/database';

export async function syncEmailDigestActivity(input: {
  userId: string;
  callerUserId: string;
  frequency: 'DAILY' | 'WEEKLY' | 'NEVER';
}) {
  const { userId, callerUserId, frequency } = input;

  if (userId !== callerUserId) {
    throw new Error('Forbidden: cannot modify notification digest preferences for other users');
  }

  await db('user_preferences')
    .where({ user_id: userId })
    .update({ digest_frequency: frequency, updated_at: new Date() });

  return { success: true };
}
